document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("freelancer-rate-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("annualLivingExpenses").value),t=parseFloat(document.getElementById("businessExpenses").value),r=parseFloat(document.getElementById("desiredProfit").value)/100,a=parseFloat(document.getElementById("billableHours").value),i=parseFloat(document.getElementById("vacationWeeks").value),s=parseFloat(document.getElementById("taxRate").value)/100,o=52-i,l=a*o,d=n+t,u=d/(1-s),c=u*(1+r),m=Math.ceil(u/l),g=Math.ceil(c/l),v=Math.ceil(1.5*g),b=m*l,$=g*l,h=v*l,p=b*(1-s),y=$*(1-s),f=h*(1-s);document.getElementById("freelancer-rate-result").innerHTML=`\n      <h3>💰 Your Freelancer Hourly Rate Analysis</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card warning">\n          <h6>⚠️ Minimum Viable Rate</h6>\n          <div class="big-number">$${m}</div>\n          <p>Covers basic expenses only<br>\n          Annual: $${b.toLocaleString()}<br>\n          Take-home: $${p.toLocaleString()}</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>✅ Sustainable Rate (Recommended)</h6>\n          <div class="big-number">$${g}</div>\n          <p>Includes ${100*r}% profit margin<br>\n          Annual: $${$.toLocaleString()}<br>\n          Take-home: $${y.toLocaleString()}</p>\n        </div>\n        \n        <div class="insight-card info">\n          <h6>🚀 Premium Rate</h6>\n          <div class="big-number">$${v}</div>\n          <p>High-value positioning<br>\n          Annual: $${h.toLocaleString()}<br>\n          Take-home: $${f.toLocaleString()}</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>📊 Rate Breakdown Analysis</h4>\n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin-top: 1rem;">\n          <div>\n            <strong>💼 Work Schedule:</strong><br>\n            ${a} hours/week × ${o} weeks<br>\n            = ${l} billable hours/year\n          </div>\n          <div>\n            <strong>💸 Annual Expenses:</strong><br>\n            Living: $${n.toLocaleString()}<br>\n            Business: $${t.toLocaleString()}<br>\n            Total: $${d.toLocaleString()}\n          </div>\n        </div>\n        <div style="margin-top: 1rem;">\n          <strong>🎯 Rate Strategy Recommendations:</strong><br>\n          • Start with <strong>$${g}/hour</strong> for most clients<br>\n          • Use $${m}/hour as your absolute minimum<br>\n          • Charge $${v}/hour for premium clients or rush jobs<br>\n          • Review and adjust rates every 6-12 months\n        </div>\n      </div>\n    `})});